<x-layout :title="$recipe->title"><div class="container narrow"><div class="breadcrumb"><a href="{{ route('recipes') }}">Zetrecepten</a><span>/</span>{{ $recipe->method }}</div><div class="page-heading"><span class="eyebrow">{{ $recipe->method }} · {{ $recipe->coffee->name }}</span><h1>{{ $recipe->title }}</h1><div class="recipe-author"><span class="avatar">{{ mb_substr($recipe->user->name,0,1) }}</span><span>Een recept van {{ $recipe->user->name }}</span></div></div><a class="recipe-coffee-link panel" href="{{ route('coffee',$recipe->coffee) }}"><x-icon name="bag" size="30"/><span><small>DIT RECEPT IS GEMAAKT VOOR</small><strong>{{ $recipe->coffee->name }} · {{ $recipe->coffee->roaster->name }}</strong></span><x-icon/></a><div class="recipe-stats"><div><small>Koffie</small><strong>{{ (float)$recipe->dose }} g</strong></div><div><small>{{ $recipe->method==='Espresso'?'Drank uit':'Water' }}</small><strong>{{ (float)$recipe->water }} g</strong></div><div><small>Ratio</small><strong>{{ $recipe->ratio() }}</strong></div><div><small>Temperatuur</small><strong>{{ $recipe->temperature }} °C</strong></div><div><small>Zetduur</small><strong>{{ intdiv($recipe->seconds,60) }}:{{ str_pad($recipe->seconds%60,2,'0',STR_PAD_LEFT) }}</strong></div></div><div class="recipe-equipment"><span><strong>Molen:</strong> {{ $recipe->grinder }}</span><span><strong>Maalstand:</strong> {{ $recipe->grind }}</span>@if($recipe->machine)<span><strong>Machine:</strong> {{ $recipe->machine }}</span> @endif </div><p class="muted">De maalstand geldt alleen voor dit molenmodel. Gebruik dit recept als startpunt en stel bij op smaak.</p>@if($recipe->roasted_at)<p>Gebruikte branddatum: {{ $recipe->roasted_at->format('d-m-Y') }}</p> @endif <section class="section recipe-steps"><span class="eyebrow">TIJD OM TE ZETTEN</span><h2>Zo doe je dat.</h2>@foreach(explode("\n",$recipe->steps) as $step)<p>{{ $step }}</p> @endforeach </section><div class="listing-toolbar">@auth<form method="post" action="{{ route('recipe.vote',$recipe) }}">@csrf<button class="button outline"><x-icon name="check"/>{{ $recipe->voters->contains(auth()->id())?'Behulpzaam gemarkeerd':'Dit helpt mij' }} ({{ $recipe->voters->count() }})</button></form><form method="post" action="{{ route('favorite') }}">@csrf<input type="hidden" name="kind" value="recipe"><input type="hidden" name="target_id" value="{{ $recipe->id }}"><button class="text-link"><x-icon name="heart"/>Bewaar recept</button></form> @else <a class="button outline" href="{{ route('login') }}">Log in om dit recept te bewaren</a> @endauth </div>@can('update',$recipe)<div class="listing-toolbar"><a class="text-link" href="{{ route('recipe.edit',$recipe) }}">Recept bewerken →</a><form method="post" action="{{ route('recipe.delete',$recipe) }}">@csrf @method('DELETE')<button class="text-button danger">Recept verwijderen</button></form></div> @endcan  @auth<details class="section-bottom"><summary>Dit recept melden</summary><form method="post" action="{{ route('report') }}" class="stack-form">@csrf<input type="hidden" name="kind" value="recipe"><input type="hidden" name="target_id" value="{{ $recipe->id }}"><label>Reden<textarea name="reason" required minlength="5"></textarea></label><button class="small-button">Melding versturen</button></form></details> @endauth </div></x-layout>